	//----W-Craft WebSquare 변환 확인: include----//
include("../js/common.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/stf.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/calendar.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/session.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/list_common.js"); // 상장관련공통함수	

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/stockSearch.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/utils.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/utils_detect.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/PopupCalendar.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/libRoundPanel.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/json2.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/report.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/controlResize.js"); // 화면 리사이징

scwin.vScrenID = "ULDSTF35620.gfm";
scwin.svrGubun = js_svrGubun; //DR전환시
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
};
scwin.fn_GetParDetail = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(rdo_MKT_ID);

	//----W-Craft WebSquare 변환 확인: Focus----//
    arrPar[1] = dts1.getCellData(dts1.getFocusedRowIndex(), "ISU_CD");

	//----W-Craft WebSquare 변환 확인: Focus----//
    arrPar[2] = dts1.getCellData(dts1.getFocusedRowIndex(), "ISU_KOR_ABBRV");

	//----W-Craft WebSquare 변환 확인: Focus----//
    arrPar[3] = dts1.getCellData(dts1.getFocusedRowIndex(), "STRT_DD");

	//----W-Craft WebSquare 변환 확인: Focus----//
    arrPar[4] = dts1.getCellData(dts1.getFocusedRowIndex(), "END_DD");
    arrPar[5] = $c.stf.getObjectValue(txb_TR_MAGAM_DD);
    return arrPar.length;
};
scwin.fn_OpenDetail = async function() {

	//----W-Craft WebSquare 변환 확인: CreateDialogFrame----//
    await $c.frame.CreateDialogFrame("ULDSTF35624.gfm", "/lstmgt/ULDSTF35624.gfm", "일별 시가총액 조회", 200, 100, 600 + 5, 620 + 20, "window");
};
scwin.fn_SetCode = function() {
    if (scwin.gLdMktTp == '9') {
        $c.stf.showObj(panel_mkt, true);
        rdo_MKT_ID.setDisabled(!"true");

	//----W-Craft WebSquare 변환 확인: setColumnProp----//
        $c.cm.setColumnProp(grd_Grid, "TR_MKT_NM", "Show", true);
        $c.stf.setObjectValue(rdo_MKT_ID, '1');
        $c.stf.showObj(txb_TR_MAGAM_DD, true);
        $c.stf.showObj(lbl_TR_MAGAM_DD, true);
    } else {
        $c.stf.showObj(panel_mkt, false);
        rdo_MKT_ID.setDisabled(!"false");

	//----W-Craft WebSquare 변환 확인: setColumnProp----//
        $c.cm.setColumnProp(grd_Grid, "TR_MKT_NM", "Show", false);
        $c.stf.setObjectValue(rdo_MKT_ID, scwin.gLdMktTp);
        $c.stf.showObj(txb_TR_MAGAM_DD, false);
        $c.stf.showObj(lbl_TR_MAGAM_DD, false);
    }
    scwin.fn_SetCtrlByMktId();
    var i = $c.stf.getObjectValue(rdo_MKT_ID);
    if (i == 1) {
        scwin.gDepCd = '2600';
    } else if (i == 2) {
        scwin.gDepCd = '3400';
    }
    var urldep = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_DEP_CD.DataID = encodeURI(urldep);

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_DEP_CD.Reset();
    var urlemp = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_EMP_NO.DataID = encodeURI(urlemp);

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_EMP_NO.Reset();
    $c.stf.setObjectValue(cmb_DEP_CD, '');
    $c.stf.setObjectValue(cmb_EMP_NO, '');
};
scwin.fn_SetCtrlByMktId = function() {
    var i = $c.stf.getObjectValue(rdo_MKT_ID);
    if (i == '2') {
        $c.stf.showObj(lbl_1, false);
        $c.stf.showObj(lbl_1_kosdaq, true);
    } else {
        $c.stf.showObj(lbl_1, true);
        $c.stf.showObj(lbl_1_kosdaq, false);
    }
};
scwin.fn_Init = function() {
    var ToDay = new Date();
    var yyyy = parseInt(ToDay.getYear(), 10);
    var str = "null^전체,";
    for (var i = yyyy; i >= 2010; i--) {
        str += i + "^" + i + ",";
    }
    str = str.substring(0, str.length - 1);
    //alert(str);
    cmb_ACNTCLS_YY.CBData = str;
};


// 종류주식 주주수요건 검색 
scwin.fn_list_sync = function() {
    if (scwin.svrGubun != "dr") {
        scwin.fn_set_trstatcd();
        scwin.fn_set_trMagamDd();
    } else {
        $c.stf.setObjectValue(txb_TR_MAGAM_DD, $c.ut.cGetToday("yyyymmdd"));
    }
    if ($c.stf.getObjectValue(txb_TR_MAGAM_DD) == "") {
        alert("시장정보 최종 배치일자가 누락입니다. 시스템관리자에게 문의바랍니다.");
        return false;
    }

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
    btn_Search.setDisabled(true);
    btn_Search.src = "../img/btn_select_d.gif";
    var acntcls_tp_cd = 'Y'; //연간
    var acntcls_yy = $c.stf.getObjectValue(cmb_ACNTCLS_YY);
    var acntcls_mm = $c.stf.getObjectValue(cmb_ACNTCLS_MM);
    if (acntcls_mm == "") {
        acntcls_mm = '%';
    }
    var isu_cd = txb_ISU_CD.value;
    if (isu_cd == "") {
        isu_cd = '%';
    }

	//----W-Craft WebSquare 변환 확인: ValueOfIndex----//
    var team_cd = cmb_DEP_CD.ValueOfIndex("VALUE", cmb_DEP_CD.getSelectedIndex());
    if (team_cd == "") {
        team_cd = '%';
    }

	//----W-Craft WebSquare 변환 확인: ValueOfIndex----//
    var charge_id = cmb_EMP_NO.ValueOfIndex("VALUE", cmb_EMP_NO.getSelectedIndex());
    if (charge_id == "") {
        charge_id = '%';
    }
    var magam_dd = $c.stf.getObjectValue(txb_TR_MAGAM_DD);

    /*
    var url = "/AdminAndDlstedDetection.do?SCREN_ID="+vScrenID+"&SCREN_PROCES_TP_CD="+SCREN_PROCS_TP_CD_01
               + "&method=getTransList&For=AVG_TCP&inputMessageId=AADD_IN&outputMessageId=AADD_OUT_AVG_TCP"
               + "&LD_MKT_TP=" + getObjectValue(rdo_MKT_ID)
               + "&ISU_CD=" + isu_cd + "&TEAM_CD=" + team_cd+ "&CHARGE_ID=" + charge_id+ "&F_SORT=Y&ACNTCLS_YY=" + acntcls_yy+ "&ACNTCLS_MM=" + acntcls_mm;	
    */

    var url = "/listingCommon.do?method=listGeneralForDynamicName&outputMessageId=AADD_OUT_AVG_TCP&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&SCREN_ID=" + scwin.vScrenID + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.lstmgt.detection.yy_avg_trans_ttl_curpriceamt.list" + "&{P}V_LD_MKT_TP=" + $c.stf.getObjectValue(rdo_MKT_ID) + "&{P}V_ACNTCLS_TP_CD=" + acntcls_tp_cd + "&{P}V_ACNTCLS_YY=" + acntcls_yy + "&{P}V_ACNTCLS_MM=" + acntcls_mm + "&{P}V_ISU_CD=" + isu_cd + "&{P}V_TEAM_CD=" + team_cd + "&{P}V_CHARGE_ID=" + charge_id + "&{P}V_MAGAM_DD=" + magam_dd;
    dts1.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: reset----//
    dts1.reset();
    $c.cm.ShowWin(grd_Grid); // 그리드명을 표기

};
scwin.fn_set_trstatcd = function() {
    var stateNm = $c.ud.fn_get_divtrstatcd(dts_TR_STATE_CD, $c.ut.cGetToday("yyyymmdd"), $c.stf.getObjectValue(rdo_MKT_ID));
    var stateCd = "N";
    if (stateNm == "장마감") {
        stateCd = "Y";
    }
    $c.stf.setObjectValue(txb_TR_STATE_CD, stateCd);
};
scwin.fn_set_trMagamDd = function() {

	//----W-Craft WebSquare 변환 확인: fn_get_divtrmagamdd----//
    var magam_dd = fn_get_divtrmagamdd(dts_TR_MAGAM_DD, $c.stf.getObjectValue(rdo_MKT_ID));
    $c.stf.setObjectValue(txb_TR_MAGAM_DD, magam_dd);
};
scwin.btn_Search_onclick = function(e) {
    scwin.fn_list_sync();
};
scwin.dts1_OnLoadCompleted = function(e) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
    btn_Search.setDisabled(false);
    btn_Search.src = "../img/btn_select.gif";
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.dts1_OnLoadError = function(e) {
    $c.stf.alert_error(dts1);
    $c.cm.CloseWin(0, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리

};

	//----W-Craft WebSquare 변환 확인: Filter----//
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.dts_DEP_CD_OnLoadCompleted = function(e) {
    $c.stf.setObjectValue(cmb_DEP_CD, '');
};
scwin.dts_EMP_NO_OnLoadCompleted = function(e) {
    $c.stf.setObjectValue(cmb_EMP_NO, '');
};
scwin.cmb_DEP_CD_OnSelChange = function(info) {
    scwin.gDepCd = $c.stf.getObjectValue(cmb_DEP_CD);
    if (scwin.gDepCd == '') {
        $c.stf.setObjectValue(cmb_EMP_NO, '');
    }

	//----W-Craft WebSquare 변환 확인: Filter----//
    dts_EMP_NO.UseFilter = true;

	//----W-Craft WebSquare 변환 확인: Filter----//
    dts_EMP_NO.Filter();
    dts_EMP_NO.sort("DEP_CD", 0);
    dts_EMP_NO.sort('', 0);
};

	//----W-Craft WebSquare 변환 확인: Filter----//
scwin.dts_EMP_NO_OnFilter = function(row) {
    if (scwin.gDepCd == "") {
        return true;
    } else {
        if (dts_EMP_NO.getCellData(row, "DEP_CD") == scwin.gDepCd || dts_EMP_NO.getCellData(row, "DEP_CD") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.btn_Excel_onclick = function(e) {
    $c.data.downloadGridViewExcel(grd_Grid, "연평균 시가총액", "", "8");
};
scwin.btn_Close_onclick = async function(e) {

	//----W-Craft WebSquare 변환 확인: CloseFrame----//
    await $c.frame.CloseFrame();
};
scwin.grd_Grid_OnUserColor = function(row, eventId) {

};
scwin.gform_onload = function() {
    scwin.fn_SetCode();
    scwin.fn_Init();
    $c.cm.fn_com_isu(txb_ISU_CD, txb_ISU_NM);
    Grd_com_isur.style.zIndex = 30;
    if (scwin.svrGubun == "dr") {
        alert("DR에서 운영될때는 [금일 장상태]가 제공되지 않습니다.");
        $c.stf.setObjectValue(txb_TR_STATE_CD, "-");
    } else {
        scwin.fn_set_trstatcd();
    }
    $c.libRoundPanel.PanelToGroupBox(panel_1);
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};

	//----W-Craft WebSquare 변환 확인: Focus----//
scwin.Grd_com_isur_OnSetFocus = function() {

	//----W-Craft WebSquare 변환 확인: Focus----//
    stFocusGrid = true;
};

	//----W-Craft WebSquare 변환 확인: Focus----//
scwin.Grd_com_isur_OnKillFocus = function() {

	//----W-Craft WebSquare 변환 확인: Focus----//
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.btn_ISU_CD_onclick = function(e) {
    $c.stockSearch.JongmokSearch(txb_ISU_CD, txb_ISU_NM, SECUGRP_ID_ST + ' ' + SECUGRP_ID_RT + ' ' + SECUGRP_ID_DR + ' ' + SECUGRP_ID_FS, js_market, "A");
};
scwin.txb_ISU_CD_onkeyup = function(e) {
    if (txb_ISU_CD.value == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스

	//----W-Craft WebSquare 변환 확인: Focus----//
            Grd_com_isur.Focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.txb_ISU_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISU_CD_onblur = function() {

	//----W-Craft WebSquare 변환 확인: Focus----//
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISU_CD.value == "") {
        txb_ISU_NM.value = "";
    }
};
scwin.rdo_MKT_ID_OnSelChange = function(info) {
    scwin.fn_SetCtrlByMktId();
};
scwin.dts_TR_STATE_CD_OnLoadError = function(e) {
    $c.stf.alert_error(dts_TR_STATE_CD);
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    scwin.fn_GetPar = fn_GetParDetail; // 수정시 인수를 넘기는 function을 fn_GetPar란 변수에 할당, (팝업화면에서 참조하는 변수명이 fn_GetPar임)
    scwin.fn_SetPar = undefined;
    scwin.fn_OpenDetail();
};
